package com.acrenex.app.activities;
import android.content.Intent;import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class ApplicationsActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Applications","Track citizen service requests and departmental progress.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT application_id,ulpin,service_type,current_department,current_status,progress,submission_date FROM applications WHERE applicant_id=? ORDER BY submission_date DESC",new String[]{uid});try{if(!c.moveToFirst())root.addView(utils.text(this,"No applications found.",15,0xff71808f,false));else do{LinearLayout box=utils.column(this);String id=c.getString(0);utils.row(box,this,"Application",id);utils.row(box,this,"Service",c.getString(2));utils.row(box,this,"ULPIN",c.getString(1));utils.row(box,this,"Department",c.getString(3));utils.row(box,this,"Status",c.getString(4));utils.row(box,this,"Progress",c.getInt(5)+"%");Button view=new Button(this);view.setText("View Application Status");box.addView(view);final String appId=id;view.setOnClickListener(v->{Intent i=new Intent(this,ApplicationStatusActivity.class);i.putExtra("application_id",appId);startActivity(i);});utils.addCard(root,box,this);}while(c.moveToNext());}finally{c.close();}utils.setScreenContentView(this, root);}
}
